SELECT 

WHERE c.company_id = #{companyId} AND c.attendance_correction_id = #{id}
FOR UPDATE OF c.status_code

SELECT 

WHERE c.company_id = #{companyId}
  AND c.status_code = 'ACR_REQUESTED'
  AND c.employee_id <> #{approverId}
  AND ( ( = #{approverId} AND  <> c.employee_id)

     OR  IS NULL OR  = c.employee_id

      )
ORDER BY c.created_at, c.attendance_correction_id
